  async function legacyAt(apiBase,path='',method='GET',body){const token=localStorage.getItem('wacrm_user');if(!token)throw Error('AUTH_REQUIRED');const response=await fetch(apiBase+path,{method,credentials:'same-origin',headers:{Authorization:'Bearer '+token,...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined});let data;try{data=await response.json();}catch{throw Error('SERVER_ERROR');}if(!response.ok||data.success===false){const error=Error(data.code||'REQUEST_FAILED');error.details=data.details;throw error;}return data.data;}
  async function legacy(path='',method='GET',body){return legacyAt(base,path,method,body);}
