  async function canonical(path,method,body,csrf){const response=await fetch(base+path,{method,credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify(body)});let data;try{data=await response.json();}catch{throw Error('SERVER_ERROR');}if(!response.ok||data.success===false)throw Error(data.code||'REQUEST_FAILED');return data.data;}
  function addFinanceSummaryStyle(){if(document.getElementById('sx-finance-summary-style'))return;const style=document.createElement('style');style.id='sx-finance-summary-style';style.textContent='#sx-finance-screen .sx-invoice-summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin:14px 0}#sx-finance-screen .sx-invoice-summary article{display:grid;gap:4px;padding:14px;border:1px solid #eaecf0;border-radius:10px;background:#fff;min-width:0}#sx-finance-screen .sx-invoice-summary span,#sx-finance-screen .sx-invoice-summary small{color:#667085}#sx-finance-screen .sx-invoice-summary strong{font-size:20px;color:#17212f}#sx-finance-screen .sx-invoice-summary-detail{display:flex;gap:14px;flex-wrap:wrap;margin:8px 0;color:#475467}@media(max-width:760px){#sx-finance-screen .sx-invoice-summary{grid-template-columns:repeat(2,minmax(0,1fr))}}';document.head.append(style);}
  const observedFinanceShell=new Set();
  const financeResizeObserver=typeof ResizeObserver==='function'?new ResizeObserver(()=>scheduleFinanceBounds()):null;
  function syncFinanceBounds(node=document.getElementById('sx-finance-screen')) {
    if(!node)return;
    const header=document.querySelector('header.MuiAppBar-root');
    const bar=header?.getBoundingClientRect(),barStyle=header&&getComputedStyle(header);
    const top=bar&&barStyle.display!=='none'&&barStyle.visibility!=='hidden'?Math.max(0,bar.bottom):0;
    const drawers=[...document.querySelectorAll('.MuiDrawer-paper')].map(drawer=>({drawer,rect:drawer.getBoundingClientRect(),style:getComputedStyle(drawer)})).filter(({drawer,rect,style})=>{
      const persistent=drawer.closest('.MuiDrawer-docked')||drawer.classList.contains('MuiDrawer-paperAnchorDockedLeft')||drawer.classList.contains('MuiDrawer-paperAnchorDockedRight')||!drawer.closest('.MuiModal-root')||(window.innerWidth>720&&drawer.querySelector('[data-sx-sidebar-list]'));
      return persistent&&style.display!=='none'&&style.visibility!=='hidden'&&rect.width>0&&rect.right>0&&rect.left<window.innerWidth&&(rect.left<=12||rect.right>=window.innerWidth-12);
    });
    let left=0,right=0;
    for(const {rect} of drawers){if(rect.left<=12)left=Math.max(left,Math.max(0,rect.right));else right=Math.max(right,Math.max(0,window.innerWidth-rect.left));}
    for(const [key,value] of [['top',top],['left',left],['right',right]]){
      const property='--sx-finance-'+key+'-inset',next=Math.ceil(value)+'px';
      if(node.style.getPropertyValue(property)!==next)node.style.setProperty(property,next);
    }
    if(financeResizeObserver){
      const current=new Set([header,...drawers.map(item=>item.drawer)].filter(Boolean));
      for(const element of observedFinanceShell)if(!current.has(element)){financeResizeObserver.unobserve(element);observedFinanceShell.delete(element);}
      for(const element of current)if(!observedFinanceShell.has(element)){financeResizeObserver.observe(element);observedFinanceShell.add(element);}
    }
  }
  let financeBoundsFrame=0;
  function scheduleFinanceBounds(){if(financeBoundsFrame)return;financeBoundsFrame=requestAnimationFrame(()=>{financeBoundsFrame=0;syncFinanceBounds();});}
