  function root(){addStyle();addFinanceSummaryStyle();addCompactInvoiceStyle();let node=document.getElementById('sx-finance-screen');if(!node){node=document.createElement('section');node.id='sx-finance-screen';node.setAttribute('aria-live','polite');document.body.append(node);}node.dir=tr('ltr','rtl');syncFinanceBounds(node);return node;}
