  function money(minor,currency='QAR'){return new Intl.NumberFormat(ar()?'ar-QA':'en-QA',{style:'currency',currency,minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(minor||0)/100);}
  function invoiceStatusLabel(status){return ({issued:tr('Issued','صادرة'),void:tr('Void','ملغاة')})[status]||status;}
  function parseQarMinor(value){const raw=String(value||'').trim();if(!/^\d{1,9}(?:\.\d{1,2})?$/.test(raw))throw Error('INVALID_PAYMENT_AMOUNT');const [whole,fraction='']=raw.split('.'),minor=Number(whole)*100+Number(fraction.padEnd(2,'0'));if(!Number.isSafeInteger(minor)||minor<1)throw Error('INVALID_PAYMENT_AMOUNT');return minor;}
  function qatarDateTimeLocal(){const parts=Object.fromEntries(new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Qatar',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date()).filter(p=>p.type!=='literal').map(p=>[p.type,p.value]));return `${parts.year}-${parts.month}-${parts.day}T${parts.hour}:${parts.minute}`;}
