  async function uploadPaymentProof(mode,path,file,csrf){const form=new FormData();form.append('proof',file,file.name);const headers=mode==='owner'?{Authorization:'Bearer '+localStorage.getItem('wacrm_user')}:{'X-CSRF-Token':csrf};const response=await fetch(base+path,{method:'POST',credentials:'same-origin',headers,body:form});let data;try{data=await response.json();}catch{throw Error('SERVER_ERROR');}if(!response.ok||data.success===false)throw Error(data.code||'REQUEST_FAILED');return data.data;}
  async function openPaymentProof(mode,paymentId,csrf){const popup=window.open('about:blank','_blank');if(!popup)return;try{const prefix=mode==='owner'?'':'/accountant',headers=mode==='owner'?{Authorization:'Bearer '+localStorage.getItem('wacrm_user')}:{'X-CSRF-Token':csrf},response=await fetch(`${base}${prefix}/payments/${encodeURIComponent(paymentId)}/proof`,{credentials:'same-origin',headers});if(!response.ok)throw Error('PAYMENT_PROOF_NOT_AVAILABLE');const url=URL.createObjectURL(await response.blob());popup.location=url;setTimeout(()=>URL.revokeObjectURL(url),60000);}catch(error){popup.close();throw error;}}
  function invoiceDate(value){if(!value)return '—';const date=new Date(value);return Number.isNaN(date.valueOf())?esc(value):new Intl.DateTimeFormat(ar()?'ar-QA':'en-QA',{dateStyle:'medium',timeZone:'Asia/Qatar'}).format(date);}
  function taxTreatment(data){if(data.taxMode==='no_tax')return tr('No tax','بدون ضريبة');const mode=data.taxMode==='inclusive'?tr('Tax included','الضريبة مشمولة'):data.taxMode==='exclusive'?tr('Tax added','تضاف الضريبة'):tr('Tax policy','السياسة الضريبية');const rate=Number.isSafeInteger(Number(data.taxRateBps))?` · ${tr('rate','النسبة')} ${Number(data.taxRateBps)/100}%`:'';return mode+rate;}
