    settingsForm.onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,notice=form.querySelector('[data-settings-message]');notice.textContent=tr('Saving…','جارٍ الحفظ…');try{const paymentPlans=[...form.querySelectorAll('[data-plan-row]')].map((row,index)=>{const label=row.querySelector('[data-plan-label]').value.trim(),installments=Number(row.querySelector('[data-plan-count]').value),intervalDays=Number(row.querySelector('[data-plan-days]').value);return {id:row.dataset.planId||`plan-${index+1}`,label,installments,intervalDays};});const f=form.elements;const input={companyName:f.companyName.value,crNumber:f.crNumber.value,address:f.address.value,footer:f.footer.value,logoDataUrl:null,invoicePrefix:f.invoicePrefix.value,paymentPlans};await generatorFetch(mode,`${root}/settings`,'PUT',input,csrf);notice.textContent=tr('Company settings saved.','تم حفظ إعدادات الشركة.');await loadInvoiceCreate(card,mode,csrf);}catch(error){notice.textContent=message(error.message);}};

    const invoiceForm=area.querySelector('#sx-generator-invoice'),customerTypeInputs=invoiceForm.querySelectorAll('[name=customerType]'),directory=area.querySelector('#sx-generator-directory'),search=area.querySelector('#sx-generator-search'),select=area.querySelector('#sx-generator-customer-select');let customerTimer=null,customerRows=[];
    customerTypeInputs.forEach(input=>input.onchange=()=>{directory.hidden=input.value==='manual';if(input.value==='manual'){select.value='';invoiceForm.dataset.customerSource='';invoiceForm.dataset.customerId='';invoiceForm.elements.customerName.value='';invoiceForm.elements.customerPhone.value='';invoiceForm.elements.customerEmail.value='';invoiceForm.elements.customerAddress.value='';}});
