    const syncProofField=()=>{const enabled=['fawran','bank_transfer'].includes(methodField.value);proofField.hidden=!enabled;if(!enabled)paymentForm.elements.proof.value='';};methodField.addEventListener('change',syncProofField);syncProofField();
    paymentForm.addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('[type=submit]');button.disabled=true;form.querySelector('[data-payment-error]')?.remove();try{const f=form.elements,receivedAt=new Date(`${f.receivedAt.value}:00+03:00`);if(!Number.isFinite(receivedAt.valueOf()))throw Error('INVALID_PAYMENT_DATE');const body={requestKey:form.dataset.requestKey||(form.dataset.requestKey=crypto.randomUUID()),method:f.method.value,amountMinor:parseQarMinor(f.amount.value),receivedAt:receivedAt.toISOString(),reference:f.reference.value,note:f.note.value},result=await invoiceWrite(mode,data.generatedDocumentId?`${generatorPath(mode)}/invoices/${encodeURIComponent(data.generatedDocumentId)}/payments`:paymentPath(mode,data.id),body,csrf);let proofError=null;if(f.proof.files?.[0])try{await uploadPaymentProof(mode,`${invoiceBase(mode)}/${encodeURIComponent(result.invoiceId||data.id)}/payments/${encodeURIComponent(result.id)}/proof`,f.proof.files[0],csrf);}catch(error){proofError=error;}await loadInvoiceDetail(card,mode,csrf,result.invoiceId||data.id);const receiptSection=card.querySelector('#sx-invoice-detail-title')?.closest('.card');if(result.receipt?.id&&receiptSection)await loadReceipt(receiptSection,mode,csrf,result.receipt.id);const status=card.closest('#sx-finance-screen')?.querySelector('#sx-finance-message');if(status)status.innerHTML=`<div class="${proofError?'notice':'success'}" role="status">${proofError?tr('Payment recorded and receipt issued. The screenshot upload failed; open the payment and retry the proof upload. The receipt is already issued.','تم تسجيل الدفعة وإصدار الإيصال. تعذر رفع الصورة؛ افتح الدفعة وأعد رفع الإثبات قبل التحقق.'):tr('Payment posted and receipt issued. A receipt will be issued after it is verified.','تم ترحيل الدفعة وإصدار الإيصال. سيصدر الإيصال بعد التحقق منها.')}${result.possibleDuplicateReference?` ${tr('A matching reference already exists; review the evidence before posting.','يوجد مرجع مطابق سابق؛ راجع الإثبات قبل الترحيل.')}`:''}${proofError?` (${esc(message(proofError.message))})`:''}</div>`;}catch(error){let messageText=message(error.message);if(error.message==='INVALID_PAYMENT_AMOUNT')messageText=tr('Enter an amount greater than zero with up to two decimal places.','أدخل مبلغًا أكبر من صفر وبحد أقصى منزلتين عشريتين.');const alert=document.createElement('div');alert.className='error';alert.dataset.paymentError='';alert.setAttribute('role','alert');alert.textContent=messageText;form.querySelector('.actions').append(alert);}finally{button.disabled=false;}});
