    const scheduleHtml=data.documentType==='generated'?schedules.map(item=>`<div class="payment"><span>${tr('Installment','القسط')} ${item.sequence} · ${invoiceDate(item.dueDate)}</span><strong>${money(item.amountMinor,data.currency)}</strong></div>`).join(''):'';
